const row = $input.first().json;

function parseObject(value, label) {
  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch {
      throw new Error(
        `${label} contains invalid JSON.`
      );
    }
  }

  return value ?? {};
}

const brief = parseObject(
  row.brief,
  'Campaign brief'
);

const content = parseObject(
  row.approved_content,
  'Approved campaign package'
);

function text(value) {
  return String(value ?? '').trim();
}

function list(values) {
  if (!Array.isArray(values)) {
    return '- None';
  }

  return values
    .map((value) => `- ${text(value)}`)
    .join('\n');
}

const angleSections = (
  content.ad_angles ?? []
).map(
  (angle) => `
### ${text(angle.angle_id)} — ${text(angle.name)}

**Awareness stage:** ${text(angle.awareness_stage)}

**Core message**

${text(angle.core_message)}

**Rationale**

${text(angle.rationale)}
`.trim()
).join('\n\n');

const adSections = (
  content.ads ?? []
).map(
  (ad) => `
### ${text(ad.ad_id)} — ${text(ad.headline)}

**Angle:** ${text(ad.angle_id)}

**Primary text**

${text(ad.primary_text)}

**Description**

${text(ad.description)}

**Call to action:** ${text(ad.call_to_action)}
`.trim()
).join('\n\n');

const imageSections = (
  content.image_prompts ?? []
).map(
  (image) => `
### ${text(image.prompt_id)} — ${text(image.concept_name)}

**Angle:** ${text(image.angle_id)}

**Prompt**

${text(image.prompt)}

**Overlay:** ${text(image.overlay_text)}
`.trim()
).join('\n\n');

const videoSections = (
  content.video_concepts ?? []
).map(
  (video) => `
### ${text(video.concept_id)} — ${text(video.concept_name)}

**Angle:** ${text(video.angle_id)}

**Duration:** ${video.duration_seconds} seconds

**Opening hook**

${text(video.opening_hook)}

**Scenes**

${list(video.scene_plan)}

**Voiceover**

${text(video.voiceover)}

**End card**

${text(video.end_card_text)}
`.trim()
).join('\n\n');

const markdown = `
# ${text(row.company_name)} — Approved Campaign Package

## Campaign information

- Campaign reference: ${text(row.campaign_code)}
- Approved version: ${row.version_number}
- Client: ${text(row.client_name)}
- Company: ${text(row.company_name)}
- Website: ${text(row.website) || 'Not provided'}
- Reviewer: ${text(row.reviewer_name)}
- Reviewer email: ${text(row.reviewer_email)}

## Campaign summary

${text(content.campaign_summary)}

## Advertising angles

${angleSections}

## Hooks

${list(
  (content.hooks ?? []).map(
    (hook) =>
      `${hook.hook_id} — ${hook.hook_text}`
  )
)}

## Approved advertisements

${adSections}

## Image prompts

${imageSections}

## Video concepts

${videoSections}

## Compliance review

### Unsupported claims

${list(
  content.compliance_review
    ?.unsupported_claims
)}

### Policy or sensitivity risks

${list(
  content.compliance_review
    ?.sensitive_or_policy_risks
)}

### Human confirmation notes

${list(
  content.compliance_review
    ?.notes_for_human_reviewer
)}

## Approval feedback

${text(row.approval_feedback) || 'No additional approval feedback.'}
`.trim();

return [
  {
    json: {
      ...row,

      folder_name:
        `${row.campaign_code} - ${row.company_name}`,

      file_name:
        `${row.campaign_code}-approved-campaign.md`,

      file_content: markdown,
    },
  },
];

